package br.com.tapeteskalke.repository; import br.com.tapeteskalke.entity.Entrega; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface EntregaRepository extends JpaRepository<Entrega,String> { boolean existsByVendaId(String vendaId); Optional<Entrega> findByVendaId(String vendaId); @EntityGraph(attributePaths={"venda","cliente","entregador"}) @Query("select e from Entrega e where e.id=:id") Optional<Entrega> detail(@Param("id")String id); @EntityGraph(attributePaths={"venda","cliente","entregador"}) @Query("select e from Entrega e order by e.dataAgendada asc nulls last") List<Entrega> allDetailed(); @EntityGraph(attributePaths={"venda","cliente","entregador"}) @Query("select e from Entrega e where lower(e.entregador.email)=lower(:email) order by e.dataAgendada asc nulls last") List<Entrega> byDriverEmail(@Param("email")String email); }
